/** On-disk side of device identity (multi-device F2): `.hub/device/key{,.pub}`,
 *  `.hub/device.yml`, synced `devices.yml`, local `.hub/allowed_signers`, and the
 *  `ledger device` operations + doctor health checks built on them.
 *
 *  Rules (docs/multi-device-spec.md §2.1, §6, §8):
 *   - the private key lives only in `.hub/device/` (0700 dir, 0600 files / owner-only ACL),
 *     is generated by ssh-keygen, never printed, never read into this process;
 *   - init never regenerates an existing key and never changes an existing device_id;
 *   - revocation is monotonic, the revoked key leaves allowed_signers FIRST (fail safe),
 *     a slot is never handed out again;
 *   - every file we parse from disk is size-capped, symlink-refused and schema-validated.
 */

import { randomBytes } from 'node:crypto';
import { constants } from 'node:fs';
import { copyFile, link, lstat, mkdir, open, rm, writeFile } from 'node:fs/promises';
import nodePath from 'node:path';
import { parse as parseYaml, stringify as stringifyYaml } from 'yaml';
import {
  DevicesError,
  REVOKE_REASON_MAX,
  acceptDevicesChange,
  deviceFileSchema,
  labelSchema,
  parseAllowedSigners,
  parseDevicesYaml,
  renderAllowedSigners,
  renderDevicesYaml,
  type DeviceEntry,
  type DeviceFile,
  type DevicesFile,
  type Signer,
} from './devices.ts';
import { renameRetry } from './fsretry.ts';
import { assertPrivateFile, ensurePrivateDir, TrustError } from './platformTrust.ts';
import { isSingleLine } from './sanitize.ts';
import {
  DEVICE_ID_RE,
  SshKeygenError,
  generateKeyPair,
  parseEd25519Pub,
  publicKeyOf,
  resolveSshKeygen,
  type Ed25519Pub,
} from './sshkey.ts';

const MAX_SMALL_FILE = 64 * 1024;
export const DEVICE_STALE_DAYS = 30;

export interface DeviceLayout {
  root: string;
  hubDir: string;
  deviceDir: string;
  keyFile: string;
  pubFile: string;
  /** `.hub/device.yml` (local identity). */
  deviceYml: string;
  /** `devices.yml` at the ledger root (synced). */
  devicesYml: string;
  allowedSigners: string;
  /** Private scratch root for verify (`withPrivateTmp`). */
  tmpDir: string;
}

export function deviceLayout(ledgerDir: string): DeviceLayout {
  const hubDir = nodePath.join(ledgerDir, '.hub');
  const deviceDir = nodePath.join(hubDir, 'device');
  return {
    root: ledgerDir,
    hubDir,
    deviceDir,
    keyFile: nodePath.join(deviceDir, 'key'),
    pubFile: nodePath.join(deviceDir, 'key.pub'),
    deviceYml: nodePath.join(hubDir, 'device.yml'),
    devicesYml: nodePath.join(ledgerDir, 'devices.yml'),
    allowedSigners: nodePath.join(hubDir, 'allowed_signers'),
    tmpDir: nodePath.join(hubDir, 'tmp'),
  };
}

/* ---------------- small-file IO (symlink-refusing, capped, atomic) ---------------- */

/** `null` = absent. Refuses symlinks and non-regular files; caps the size. No O_NOFOLLOW
 *  here (I1: only platformTrust uses it, and win32 has none): lstat → open → fstat and require
 *  the same dev+ino, so a path swapped for a symlink between the two calls is refused. */
async function readSmall(path: string, max = MAX_SMALL_FILE): Promise<string | null> {
  const name = nodePath.basename(path);
  let before;
  try {
    before = await lstat(path, { bigint: true });
  } catch (err) {
    if ((err as NodeJS.ErrnoException).code === 'ENOENT') return null;
    throw err;
  }
  if (before.isSymbolicLink()) throw new DevicesError('UNSAFE_FILE', `${name} is a symlink — refusing`);
  if (!before.isFile()) throw new DevicesError('UNSAFE_FILE', `${name} is not a regular file`);
  const fh = await open(path, 'r');
  try {
    const st = await fh.stat({ bigint: true });
    if (!st.isFile() || st.dev !== before.dev || st.ino !== before.ino) {
      throw new DevicesError('UNSAFE_FILE', `${name} changed while being opened — refusing`);
    }
    if (st.size > BigInt(max)) throw new DevicesError('UNSAFE_FILE', `${name} is too large`);
    return await fh.readFile('utf8');
  } finally {
    await fh.close();
  }
}

/** tmp (exclusive create, 0600) in the same directory + rename. */
async function writeAtomic(path: string, data: string): Promise<void> {
  const tmp = nodePath.join(nodePath.dirname(path), `.${randomBytes(6).toString('hex')}.tmp`);
  try {
    await writeFile(tmp, data, { encoding: 'utf8', mode: 0o600, flag: 'wx' });
    await renameRetry(tmp, path);
  } catch (err) {
    await rm(tmp, { force: true }).catch(() => undefined);
    throw err;
  }
}

async function ensureDirs(l: DeviceLayout): Promise<void> {
  if (process.platform === 'win32') {
    await ensurePrivateDir(l.hubDir);
  } else {
    await mkdir(l.root, { recursive: true, mode: 0o700 });
    await mkdir(l.hubDir, { recursive: true, mode: 0o700 });
  }
  await ensurePrivateDir(l.deviceDir);
}

/* ---------------- readers ---------------- */

export async function readDeviceFile(l: DeviceLayout): Promise<DeviceFile | null> {
  const text = await readSmall(l.deviceYml);
  if (text === null) return null;
  let raw: unknown;
  try {
    raw = parseYaml(text, { maxAliasCount: 0 });
  } catch {
    raw = null;
  }
  const res = deviceFileSchema.safeParse(raw);
  if (!res.success) {
    throw new DevicesError('DEVICE_INVALID', '.hub/device.yml is invalid — refusing (it is never regenerated automatically)');
  }
  return res.data;
}

async function writeDeviceFile(l: DeviceLayout, d: DeviceFile): Promise<void> {
  await writeAtomic(l.deviceYml, stringifyYaml(deviceFileSchema.parse(d), { lineWidth: 0 }));
}

export async function readDevices(l: DeviceLayout): Promise<DevicesFile | null> {
  const text = await readSmall(l.devicesYml);
  return text === null ? null : parseDevicesYaml(text);
}

export async function readSigners(l: DeviceLayout): Promise<Signer[]> {
  const text = await readSmall(l.allowedSigners);
  return text === null ? [] : parseAllowedSigners(text);
}

async function readLocalPub(l: DeviceLayout): Promise<Ed25519Pub | null> {
  const text = await readSmall(l.pubFile, 1024);
  if (text === null) return null;
  const pub = parseEd25519Pub(text, { allowComment: true });
  if (pub === null) throw new DevicesError('KEY_INVALID', '.hub/device/key.pub is not an ed25519 public key');
  return pub;
}

/* ---------------- device init ---------------- */

export interface InitOptions {
  label?: string;
  /** Register this device as the TOFU root in devices.yml (refused if one exists). */
  root?: boolean;
  /** Test seam. */
  bin?: string;
  now?: Date;
}

export interface InitResult {
  deviceId: string;
  label: string;
  slot: string;
  fingerprint: string;
  keyCreated: boolean;
  deviceYmlCreated: boolean;
  registeredRoot: boolean;
  inDevicesYml: boolean;
}

function defaultLabel(): string {
  return process.platform === 'darwin' ? 'mac' : process.platform === 'win32' ? 'win' : 'linux';
}

/** Exclusive publish of the freshly generated private key: `link` fails with EEXIST
 *  when a racing init won; filesystems without hard links fall back to an exclusive copy. */
async function publishKey(src: string, dest: string): Promise<boolean> {
  try {
    await link(src, dest);
    return true;
  } catch (err) {
    const code = (err as NodeJS.ErrnoException).code;
    if (code === 'EEXIST') return false;
    try {
      await copyFile(src, dest, constants.COPYFILE_EXCL);
      return true;
    } catch (err2) {
      if ((err2 as NodeJS.ErrnoException).code === 'EEXIST') return false;
      throw err2;
    }
  }
}

async function exists(path: string): Promise<boolean> {
  try {
    await lstat(path);
    return true;
  } catch (err) {
    if ((err as NodeJS.ErrnoException).code === 'ENOENT') return false;
    throw err;
  }
}

/** Idempotent. Never regenerates a key, never rewrites an existing device_id. */
export async function initDevice(ledgerDir: string, opts: InitOptions = {}): Promise<InitResult> {
  if (opts.label !== undefined && !labelSchema.safeParse(opts.label).success) {
    throw new DevicesError('LABEL_INVALID', 'label: lowercase letters, digits, - (max 32)');
  }
  const bin = opts.bin ?? (await resolveSshKeygen()); // fail closed before anything is created
  const l = deviceLayout(ledgerDir);
  const existing = await readDeviceFile(l); // a broken identity is refused before anything is created
  await ensureDirs(l);

  /* ---- key ---- */
  let keyCreated = false;
  let pub: Ed25519Pub;
  const hasKey = await exists(l.keyFile);
  if (hasKey) {
    await assertPrivateFile(l.keyFile, { secret: true });
    const onDisk = await readLocalPub(l);
    pub = onDisk ?? (await publicKeyOf(l.keyFile, bin));
    if (onDisk === null) await writeAtomic(l.pubFile, `${pub.line}\n`);
    else if ((await publicKeyOf(l.keyFile, bin)).line !== pub.line) {
      throw new DevicesError('KEY_MISMATCH', 'key.pub does not belong to the private key — refusing');
    }
  } else {
    if (await exists(l.pubFile)) {
      throw new DevicesError('KEY_INVALID', 'key.pub exists but the private key is missing — refusing to generate a new identity');
    }
    const gen = nodePath.join(l.deviceDir, `.gen-${randomBytes(6).toString('hex')}`);
    await ensurePrivateDir(gen);
    try {
      const genKey = nodePath.join(gen, 'key');
      await generateKeyPair(genKey, bin);
      const fresh = parseEd25519Pub((await readSmall(`${genKey}.pub`, 1024)) ?? '', { allowComment: true });
      if (fresh === null) throw new SshKeygenError('INVALID', 'ssh-keygen produced no usable public key');
      keyCreated = await publishKey(genKey, l.keyFile);
      if (keyCreated) {
        pub = fresh;
        await writeAtomic(l.pubFile, `${fresh.line}\n`);
      } else {
        // A racing init published first: adopt its key, never overwrite it.
        const theirs = await readLocalPub(l);
        pub = theirs ?? (await publicKeyOf(l.keyFile, bin));
        if (theirs === null) await writeAtomic(l.pubFile, `${pub.line}\n`);
      }
    } finally {
      await rm(gen, { recursive: true, force: true }).catch(() => undefined);
    }
    await assertPrivateFile(l.keyFile, { secret: true });
  }

  /* ---- device.yml: id is kept; fingerprint recorded ---- */
  let identity: DeviceFile;
  let deviceYmlCreated = false;
  if (existing === null) {
    identity = { device_id: pub.deviceId, label: opts.label ?? defaultLabel(), slot: '', key_fp: pub.fingerprint };
    await writeDeviceFile(l, identity);
    deviceYmlCreated = true;
  } else {
    if (existing.key_fp !== undefined && existing.key_fp !== pub.fingerprint) {
      throw new DevicesError('KEY_MISMATCH', 'device.yml records a different key fingerprint — refusing to touch it');
    }
    identity = existing;
    const labelChange = opts.label !== undefined && opts.label !== existing.label;
    if (labelChange && existing.key_fp !== undefined) {
      throw new DevicesError('LABEL_LOCKED', 'device is already initialised; its label is part of its registration');
    }
    if (existing.key_fp === undefined || labelChange) {
      identity = { ...existing, label: opts.label ?? existing.label, key_fp: pub.fingerprint };
      await writeDeviceFile(l, identity);
    }
  }

  /* ---- optional TOFU root ---- */
  let registeredRoot = false;
  let devices = await readDevices(l);
  if (opts.root === true) {
    const mine = devices?.devices.find((d) => d.id === identity.device_id);
    if (devices !== null && (mine === undefined || mine.pubkey !== pub.line || mine.slot !== '')) {
      throw new DevicesError('ROOT_EXISTS', 'devices.yml already exists and is not this device\'s root entry — refusing');
    }
    if (devices === null) {
      if (identity.slot !== '') throw new DevicesError('ROOT_SLOT', 'only the primary (slot "") can be the TOFU root');
      const entry: DeviceEntry = {
        id: identity.device_id,
        label: identity.label,
        slot: '',
        pubkey: pub.line,
        added: (opts.now ?? new Date()).toISOString(),
        added_by: identity.device_id,
        revoked: null,
        role: 'owner',
      };
      const file: DevicesFile = { devices: [entry] };
      const verdict = acceptDevicesChange(null, file, pub.line, new Set(), { allowRoot: true });
      if (!verdict.ok) throw new DevicesError('ROOT_INVALID', `root registration refused: ${verdict.reason}`);
      // Trust first, record second: a crash in between leaves only a self-trusted key.
      await mergeSigner(l, { id: entry.id, pubkey: pub.line });
      await writeAtomic(l.devicesYml, renderDevicesYaml(file));
      devices = file;
      registeredRoot = true;
    } else {
      await mergeSigner(l, { id: identity.device_id, pubkey: pub.line }); // idempotent
    }
  }

  return {
    deviceId: identity.device_id,
    label: identity.label,
    slot: identity.slot,
    fingerprint: pub.fingerprint,
    keyCreated,
    deviceYmlCreated,
    registeredRoot,
    inDevicesYml: devices?.devices.some((d) => d.id === identity.device_id && d.pubkey === pub.line) ?? false,
  };
}

/** Add one signer; the same principal with a DIFFERENT key is a conflict, never a silent replace. */
async function mergeSigner(l: DeviceLayout, s: Signer): Promise<boolean> {
  const signers = await readSigners(l);
  const have = signers.find((x) => x.id === s.id);
  if (have !== undefined) {
    if (have.pubkey !== s.pubkey) throw new DevicesError('SIGNER_CONFLICT', `${s.id} is already trusted with a different key`);
    return false;
  }
  await writeAtomic(l.allowedSigners, renderAllowedSigners([...signers, s]));
  return true;
}

/* ---------------- list / approve / revoke ---------------- */

export interface DeviceRow {
  id: string;
  label: string;
  slot: string;
  fingerprint: string;
  status: 'active' | 'revoked';
  trusted: boolean;
  self: boolean;
  lastSeen: string | null;
}

export async function listDevices(ledgerDir: string): Promise<DeviceRow[]> {
  const l = deviceLayout(ledgerDir);
  const devices = await readDevices(l);
  if (devices === null) return [];
  const signers = new Set((await readSigners(l)).map((s) => `${s.id} ${s.pubkey}`));
  const self = await readDeviceFile(l);
  return devices.devices.map((d) => ({
    id: d.id,
    label: d.label,
    slot: d.slot,
    fingerprint: parseEd25519Pub(d.pubkey)?.fingerprint ?? '?',
    status: d.revoked === null ? 'active' : 'revoked',
    trusted: d.revoked === null && signers.has(`${d.id} ${d.pubkey}`),
    self: self?.device_id === d.id,
    lastSeen: d.last_seen ?? null,
  }));
}

function requireId(id: string): void {
  if (!DEVICE_ID_RE.test(id)) throw new DevicesError('ID_INVALID', 'device id must look like d_xxxxxxxxxx (a-z, 2-7)');
}

/** The acting device must itself be a registered, non-revoked member whose local key matches. */
async function requireMember(l: DeviceLayout): Promise<{ self: DeviceFile; devices: DevicesFile }> {
  const self = await readDeviceFile(l);
  const devices = await readDevices(l);
  const pub = await readLocalPub(l);
  const mine = devices?.devices.find((d) => d.id === self?.device_id);
  if (self === null || devices === null || pub === null || mine === undefined || mine.pubkey !== pub.line) {
    throw new DevicesError('NOT_MEMBER', 'this device is not registered in devices.yml (ledger device init --root on the first device)');
  }
  if (mine.revoked !== null) throw new DevicesError('NOT_MEMBER', 'this device is revoked');
  return { self, devices };
}

/** Approve = trust that device's key locally (`.hub/allowed_signers`). */
export async function approveDevice(ledgerDir: string, id: string): Promise<{ added: boolean }> {
  requireId(id);
  const l = deviceLayout(ledgerDir);
  const { devices } = await requireMember(l);
  const target = devices.devices.find((d) => d.id === id);
  if (target === undefined) throw new DevicesError('NOT_FOUND', `${id} is not in devices.yml`);
  if (target.revoked !== null) throw new DevicesError('REVOKED', `${id} is revoked — a revoked key is never trusted again`);
  return { added: await mergeSigner(l, { id, pubkey: target.pubkey }) };
}

/** Monotonic. The key leaves allowed_signers first (fail safe), then the record is written. */
export async function revokeDevice(
  ledgerDir: string,
  id: string,
  reason: string,
  now: Date = new Date(),
): Promise<void> {
  requireId(id);
  const why = reason.trim();
  if (why === '' || why.length > REVOKE_REASON_MAX || !isSingleLine(why)) {
    throw new DevicesError('REASON_INVALID', `--reason is required: one line, max ${REVOKE_REASON_MAX} chars`);
  }
  const l = deviceLayout(ledgerDir);
  const { self, devices } = await requireMember(l);
  if (id === self.device_id) throw new DevicesError('SELF_REVOKE', 'refusing to revoke this device itself — revoke it from another device');
  const target = devices.devices.find((d) => d.id === id);
  if (target === undefined) throw new DevicesError('NOT_FOUND', `${id} is not in devices.yml`);
  if (target.revoked !== null) throw new DevicesError('REVOKED', `${id} is already revoked (revocation is permanent)`);
  const signers = await readSigners(l);
  await writeAtomic(l.allowedSigners, renderAllowedSigners(signers.filter((s) => s.id !== id)));
  const next: DevicesFile = {
    devices: devices.devices.map((d) =>
      d.id === id ? { ...d, revoked: { at: now.toISOString(), by: self.device_id, reason: why } } : d,
    ),
  };
  await writeAtomic(l.devicesYml, renderDevicesYaml(next));
}

/* ---------------- doctor ---------------- */

export interface DeviceCheck {
  id: string;
  status: 'ok' | 'warn' | 'fail' | 'info';
  detail: string;
}

/** Checks only appear once device identity exists (a plain local ledger prints nothing new). */
export async function deviceHealth(ledgerDir: string, nowMs: number = Date.now()): Promise<DeviceCheck[]> {
  const l = deviceLayout(ledgerDir);
  const out: DeviceCheck[] = [];
  const keyExists = await exists(l.keyFile).catch(() => false);
  const devicesExists = await exists(l.devicesYml).catch(() => false);
  if (!keyExists && !devicesExists && !(await exists(l.allowedSigners).catch(() => false))) return out;

  let devices: DevicesFile | null = null;
  try {
    devices = await readDevices(l);
  } catch (err) {
    out.push({ id: 'device_key', status: 'fail', detail: `device key: ${err instanceof Error ? err.message : 'devices.yml unreadable'}` });
    return out;
  }

  /* ---- device_key ---- */
  const problems: string[] = [];
  let note = 'present, private';
  let self: DeviceFile | null = null;
  try {
    self = await readDeviceFile(l);
  } catch (err) {
    problems.push((err as Error).message);
  }
  let pub: Ed25519Pub | null = null;
  if (!keyExists) {
    if (self !== null && devices?.devices.some((d) => d.id === self?.device_id)) {
      problems.push('private key is MISSING although this device is registered');
    }
  } else {
    try {
      await assertPrivateFile(l.keyFile, { secret: true });
    } catch (err) {
      problems.push(err instanceof TrustError ? `key file is not private (${err.code})` : 'key file cannot be inspected');
    }
    try {
      pub = await readLocalPub(l);
    } catch (err) {
      problems.push((err as Error).message);
    }
    if (pub === null && problems.length === 0) problems.push('key.pub is missing');
    if (pub !== null) {
      if (self?.key_fp !== undefined && self.key_fp !== pub.fingerprint) problems.push('device.yml fingerprint does not match key.pub');
      const mine = devices?.devices.find((d) => d.id === self?.device_id);
      if (devices !== null && mine === undefined) note = 'present, private, NOT registered in devices.yml';
      else if (mine !== undefined && mine.pubkey !== pub.line) problems.push('key.pub differs from this device\'s devices.yml entry');
      else if (mine?.revoked) problems.push('this device is REVOKED in devices.yml');
    }
  }
  if (keyExists || problems.length > 0) {
    out.push(
      problems.length > 0
        ? { id: 'device_key', status: 'fail', detail: `device key: ${problems.join('; ')}` }
        : { id: 'device_key', status: note.includes('NOT') ? 'warn' : 'ok', detail: `device key: ${note}${pub ? ` (${pub.fingerprint})` : ''}` },
    );
  }

  /* ---- device_signers ---- */
  try {
    const signers = await readSigners(l);
    if (signers.length > 0 || (await exists(l.allowedSigners))) {
      const bad: string[] = [];
      for (const s of signers) {
        const entry = devices?.devices.find((d) => d.id === s.id);
        if (entry === undefined) bad.push(`${s.id} not in devices.yml`);
        else if (entry.pubkey !== s.pubkey) bad.push(`${s.id} key differs from devices.yml`);
        else if (entry.revoked !== null) bad.push(`${s.id} is revoked but still trusted`);
      }
      out.push(
        bad.length > 0
          ? { id: 'device_signers', status: 'fail', detail: `allowed_signers: ${bad.join('; ')}` }
          : { id: 'device_signers', status: 'ok', detail: `allowed_signers: ${signers.length} trusted key(s)` },
      );
    }
  } catch (err) {
    out.push({ id: 'device_signers', status: 'fail', detail: `allowed_signers: ${err instanceof DevicesError ? err.message : 'unreadable'}` });
  }

  /* ---- devices_stale (only when last_seen is recorded) ---- */
  const stale: string[] = [];
  let seenAny = false;
  for (const d of devices?.devices ?? []) {
    if (d.revoked !== null || d.last_seen === undefined) continue;
    seenAny = true;
    // Math.abs: a clock that jumped (sleep/wake, NTP) must not make a device look "from the future".
    if (Math.abs(nowMs - Date.parse(d.last_seen)) > DEVICE_STALE_DAYS * 86_400_000) stale.push(d.id);
  }
  if (seenAny) {
    out.push(
      stale.length > 0
        ? { id: 'devices_stale', status: 'warn', detail: `devices unseen > ${DEVICE_STALE_DAYS} days: ${stale.slice(0, 5).join(', ')} — consider \`ledger device revoke <id> --reason …\`` }
        : { id: 'devices_stale', status: 'ok', detail: `devices seen within ${DEVICE_STALE_DAYS} days` },
    );
  }
  return out;
}
